"""
export_service.py — Writes the actual generated dataset (never sample or
hardcoded data) to disk in various formats, for download.

Every file written here is derived directly from the live DataFrame /
report objects passed in by app.py — nothing is pre-baked.
"""

from __future__ import annotations

import csv
import json
import os
from datetime import datetime

import pandas as pd

SYNTHETIC_DISCLAIMER = (
    "SYNTHETIC DATA — generated by LeaseSynth AI. Every record is fictitious "
    "(see is_synthetic=True on every row). Figures are illustrative outputs of "
    "configurable statistical assumptions, not verified market valuations, and "
    "do not represent any real tenant, property, or lease agreement."
)


def _timestamp() -> str:
    return datetime.now().strftime("%Y%m%d_%H%M%S")


def export_csv(df: pd.DataFrame, directory: str, filename: str = None) -> str:
    filename = filename or f"LeaseSynth_Dataset_{_timestamp()}.csv"
    path = os.path.join(directory, filename)
    df.to_csv(path, index=False)
    return path


def export_json(df: pd.DataFrame, directory: str, filename: str = None) -> str:
    """Writes the dataset as JSON, wrapped with metadata (record count,
    generation time, synthetic-data disclaimer) alongside the records,
    rather than stuffing a disclaimer into row data.
    """
    filename = filename or f"LeaseSynth_Dataset_{_timestamp()}.json"
    path = os.path.join(directory, filename)
    payload = {
        "metadata": {
            "source": "LeaseSynth AI",
            "is_synthetic_data": True,
            "disclaimer": SYNTHETIC_DISCLAIMER,
            "generated_at": datetime.now().isoformat(timespec="seconds"),
            "record_count": int(len(df)),
        },
        "records": json.loads(df.to_json(orient="records", date_format="iso")),
    }
    with open(path, "w", encoding="utf-8") as f:
        json.dump(payload, f, indent=2)
    return path


def export_validation_csv(report: dict, directory: str, filename: str = None) -> str:
    """Flattens the validation report into a CSV with a summary section
    followed by a detailed per-row error section.
    """
    filename = filename or f"LeaseSynth_ValidationReport_{_timestamp()}.csv"
    path = os.path.join(directory, filename)

    with open(path, "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(["LeaseSynth AI — Data Validation Report"])
        writer.writerow(["Generated at", datetime.now().isoformat(timespec="seconds")])
        writer.writerow([])
        writer.writerow(["Summary metric", "Value"])
        writer.writerow(["Total records", report.get("total_records", 0)])
        writer.writerow(["Valid records", report.get("valid_records", 0)])
        writer.writerow(["Invalid records", report.get("invalid_records", 0)])
        writer.writerow(["Duplicate records", report.get("duplicate_records", 0)])
        writer.writerow(["Missing value cells", report.get("missing_value_cells", 0)])
        writer.writerow(["Data quality percentage", report.get("data_quality_percentage", 0)])
        writer.writerow([])
        writer.writerow(["Check", "Rows flagged"])
        for check_name, count in report.get("checks", {}).items():
            writer.writerow([check_name, count])
        writer.writerow([])
        writer.writerow(["Row index", "Lease ID", "Errors"])
        for err in report.get("errors", []):
            writer.writerow([err["row_index"], err["lease_id"], "; ".join(err["errors"])])
        if report.get("truncated"):
            writer.writerow(["...", "...", "error list truncated — see full JSON report in the app"])
    return path


def export_summary_report(df: pd.DataFrame, kpis: dict, validation_report: dict, directory: str, filename: str = None) -> str:
    """A short, human-readable text summary of a generation run."""
    filename = filename or f"LeaseSynth_Summary_{_timestamp()}.txt"
    path = os.path.join(directory, filename)

    lines = []
    lines.append("LEASESYNTH AI — DATASET SUMMARY REPORT")
    lines.append("=" * 50)
    lines.append(f"Generated at: {datetime.now().isoformat(timespec='seconds')}")
    lines.append("")
    lines.append(SYNTHETIC_DISCLAIMER)
    lines.append("")
    lines.append("KEY METRICS")
    lines.append("-" * 50)
    for key, value in kpis.items():
        label = key.replace("_", " ").title()
        lines.append(f"{label:35s} {value}")
    lines.append("")
    lines.append("DATA QUALITY")
    lines.append("-" * 50)
    lines.append(f"{'Total records':35s} {validation_report.get('total_records', 0)}")
    lines.append(f"{'Valid records':35s} {validation_report.get('valid_records', 0)}")
    lines.append(f"{'Invalid records':35s} {validation_report.get('invalid_records', 0)}")
    lines.append(f"{'Data quality percentage':35s} {validation_report.get('data_quality_percentage', 0)}%")
    lines.append("")
    if not df.empty:
        lines.append("BREAKDOWN BY PROPERTY TYPE")
        lines.append("-" * 50)
        for ptype, count in df["property_type"].value_counts().items():
            lines.append(f"{ptype:25s} {count} leases")
        lines.append("")
        lines.append("BREAKDOWN BY LEASE STATUS")
        lines.append("-" * 50)
        for status, count in df["lease_status"].value_counts().items():
            lines.append(f"{status:25s} {count} leases")

    with open(path, "w", encoding="utf-8") as f:
        f.write("\n".join(lines) + "\n")
    return path
